button.style:
width:52px;height:52px;border-radius:50%;
background:var(--wink-primary,#0055b7);
border:none;color:#fff;font-size:1.2rem;
box-shadow:0 4px 16px rgba(0,0,0,.25);
cursor:pointer;position:relative;
display:flex;align-items:center;justify-content:center;
transition:transform .15s ease;

span.style:
display:none;position:absolute;
top:6px;right:6px;
min-width:18px;height:18px;
border-radius:9px;
background:#e53935;color:#fff;
font-size:.65rem;font-weight:700;
line-height:18px;text-align:center;
padding:0 4px;

div.style:
display:none;
position:absolute;bottom:62px;right:0;
width:340px;max-height:480px;
background:#fff;border-radius:12px;
box-shadow:0 8px 32px rgba(0,0,0,.18);
overflow:hidden;
border:1px solid #e8ecf0;

template.script:
(function() {
    'use strict';

    var POLL_INTERVAL = 30000; // 30 seconds
    var panel = document.getElementById('wink-notif-panel');
    var btn   = document.getElementById('wink-notif-btn');
    var badge = document.getElementById('wink-notif-badge');
    var list  = document.getElementById('wink-notif-list');
    var loading = document.getElementById('wink-notif-loading');
    var readAllBtn = document.getElementById('wink-notif-read-all');
    var panelOpen = false;

    if (!btn || !panel) return;

    /* ── JSON-RPC helper ── */
    function rpc(url, params) {
        return fetch(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}})
        }).then(function(r) { return r.json(); })
          .then(function(r) { return r.result; });
    }

    /* ── Badge update ── */
    function updateBadge(count) {
        if (count > 0) {
            badge.textContent = count > 99 ? '99+' : count;
            badge.style.display = 'block';
        } else {
            badge.style.display = 'none';
        }
    }

    /* ── Fetch unread count (polling) ── */
    function fetchCount() {
        rpc('/my/notifications/count').then(function(res) {
            if (res) updateBadge(res.count || 0);
        }).catch(function() {});
    }

    /* ── Render notification item ── */
    function renderItem(n) {
        var item = document.createElement('a');
        item.href = n.link || '/my/requests';
        item.className = 'wink-notif-item';
        item.setAttribute('data-id', n.id);
        item.style.cssText = [
            'display:flex;align-items:flex-start;gap:12px;',
            'padding:12px 16px;text-decoration:none;',
            'border-bottom:1px solid #f5f7fa;',
            'transition:background .12s;',
            n.is_read ? 'background:#fff;' : 'background:#f0f5ff;'
        ].join('');

        var iconWrap = document.createElement('div');
        iconWrap.style.cssText = [
            'width:36px;height:36px;border-radius:50%;flex-shrink:0;',
            'display:flex;align-items:center;justify-content:center;',
            'background:', n.is_read ? '#f0f2f5' : 'var(--wink-primary,#0055b7)', ';',
            'color:', n.is_read ? '#888' : '#fff', ';font-size:.85rem;'
        ].join('');
        iconWrap.innerHTML = '<i class="fa ' + n.icon + '"></i>';

        var body = document.createElement('div');
        body.style.cssText = 'flex:1;min-width:0;';

        var title = document.createElement('div');
        title.style.cssText = 'font-size:.8rem;font-weight:' + (n.is_read ? '400' : '600') + ';color:#1a1a2e;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';
        title.textContent = n.record_name || 'Request Update';

        var author = document.createElement('div');
        author.style.cssText = 'font-size:.75rem;color:#555;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;';
        author.textContent = n.author + ': ' + (n.body || '');

        var date = document.createElement('div');
        date.style.cssText = 'font-size:.7rem;color:#aaa;margin-top:3px;';
        date.textContent = n.date || '';

        body.appendChild(title);
        body.appendChild(author);
        body.appendChild(date);
        item.appendChild(iconWrap);
        item.appendChild(body);

        /* mark read on click, close panel, then navigate */
        item.addEventListener('click', function(e) {
            e.preventDefault();
            var dest = n.link || '/my/requests';
            if (typeof n.id === 'number') {
                rpc('/my/notifications/read', {message_ids: [n.id]}).catch(function(){});
            }
            item.style.background = '#fff';
            iconWrap.style.background = '#f0f2f5';
            iconWrap.style.color = '#888';
            title.style.fontWeight = '400';
            panelOpen = false;
            panel.style.display = 'none';
            window.location.href = dest;
        });

        return item;
    }

    /* ── Load notification list ── */
    function loadList() {
        if (loading) loading.style.display = 'block';
        rpc('/my/notifications/list').then(function(res) {
            if (loading) loading.style.display = 'none';
            list.innerHTML = '';
            var items = (res && res.notifications) ? res.notifications : [];
            if (!items.length) {
                var empty = document.createElement('div');
                empty.style.cssText = 'padding:40px 16px;text-align:center;color:#aaa;font-size:.85rem;';
                empty.innerHTML = '<i class="fa fa-check-circle fa-2x mb-2 d-block" style="color:#4caf50;"></i>All caught up!';
                list.appendChild(empty);
                return;
            }
            items.forEach(function(n) {
                list.appendChild(renderItem(n));
            });
            /* update badge from loaded list */
            var unread = items.filter(function(n) { return !n.is_read; }).length;
            updateBadge(unread);
        }).catch(function() {
            if (loading) loading.style.display = 'none';
        });
    }

    /* ── Toggle panel ── */
    btn.addEventListener('click', function(e) {
        e.stopPropagation();
        panelOpen = !panelOpen;
        panel.style.display = panelOpen ? 'block' : 'none';
        btn.style.transform = panelOpen ? 'scale(0.95)' : 'scale(1)';
        if (panelOpen) loadList();
    });

    /* ── Close on outside click ── */
    document.addEventListener('click', function(e) {
        if (panelOpen && !panel.contains(e.target) && e.target !== btn) {
            panelOpen = false;
            panel.style.display = 'none';
            btn.style.transform = 'scale(1)';
        }
    });

    /* ── Mark all read ── */
    if (readAllBtn) {
        readAllBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            rpc('/my/notifications/read', {mark_all: true}).then(function() {
                updateBadge(0);
                /* visually mark all read */
                var items = list.querySelectorAll('.wink-notif-item');
                items.forEach(function(item) {
                    item.style.background = '#fff';
                });
            }).catch(function(){});
        });
    }

    /* ── Initial count fetch + start polling ── */
    fetchCount();
    setInterval(fetchCount, POLL_INTERVAL);

})();
